from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from constance import config

class ClientEmailBrandingView(APIView):
    permission_classes = [IsAuthenticated]

    def patch(self, request, client_code):
        if not request.user.client_memberships.filter(client_code=client_code, role="admin").exists():
            return Response({"error": "Unauthorized to configure client branding"}, status=403)

        header_text = request.data.get("header_text")
        support_url = request.data.get("support_url")

        if header_text is not None:
            setattr(config, f"EMAIL_HEADER_{client_code}", header_text)
        if support_url is not None:
            setattr(config, f"SUPPORT_URL_{client_code}", support_url)

        return Response({"status": "branding_updated", "client_code": client_code})
